import{_ as n,o as e,c as s,a2 as o}from"./chunks/framework.OWFDNrRT.js";const u=JSON.parse('{"title":"ADR-011 — WinUI 3 Desktop Companion App","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-011-desktop-companion.md","filePath":"adr/ADR-011-desktop-companion.md","lastUpdated":1774563550000}'),i={name:"adr/ADR-011-desktop-companion.md"};function t(l,a,p,r,d,c){return e(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="adr-011-—-winui-3-desktop-companion-app" tabindex="-1">ADR-011 — WinUI 3 Desktop Companion App <a class="header-anchor" href="#adr-011-—-winui-3-desktop-companion-app" aria-label="Permalink to &quot;ADR-011 — WinUI 3 Desktop Companion App&quot;">​</a></h1><p><strong>Date</strong>: 2026-03-14 <strong>Status</strong>: Accepted <strong>Deciders</strong>: kooshapari <strong>Related</strong>: ADR-009 (Runtime Orchestration), ADR-008 (Wrap Don&#39;t Handroll)</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The DINOForge in-game UI (F9 debug panel, F10 mod menu) requires a full game launch to evaluate any UI or pack configuration changes. This creates a high iteration cost:</p><ul><li>Game launch takes ~90 seconds on typical hardware</li><li>BepInEx plugin load adds ~10 seconds</li><li>Pack reload on change requires re-launch or F9 hot reload</li><li>Debugging UI layout issues (e.g. blank panel body) is difficult without immediate feedback</li></ul><p>Developers and mod authors need a way to:</p><ol><li>Preview pack lists and pack status without launching DINO</li><li>Enable/disable packs and see the effect on load order immediately</li><li>Inspect debug panel data (entity counts, system state, errors) from a logged dump</li><li>Evaluate F9/F10 UI component layout changes without game relaunch</li></ol><hr><h2 id="options-considered" tabindex="-1">Options Considered <a class="header-anchor" href="#options-considered" aria-label="Permalink to &quot;Options Considered&quot;">​</a></h2><h3 id="option-a-—-winui-3-windowsappsdk-chosen" tabindex="-1">Option A — WinUI 3 / WindowsAppSDK (Chosen) <a class="header-anchor" href="#option-a-—-winui-3-windowsappsdk-chosen" aria-label="Permalink to &quot;Option A — WinUI 3 / WindowsAppSDK (Chosen)&quot;">​</a></h3><p><strong>Framework</strong>: WindowsAppSDK 1.6, WinUI 3, Mica background, NavigationView <strong>VM layer</strong>: CommunityToolkit.Mvvm (ObservableObject, RelayCommand) <strong>DI</strong>: Microsoft.Extensions.Hosting + DI container <strong>Target</strong>: <code>net8.0-windows</code>, unpackaged deployment</p><p>Pros:</p><ul><li>First-class Windows 11 Fluent design (Mica, acrylic, rounded corners)</li><li>Native Win32 integration (no Electron overhead)</li><li>CommunityToolkit.WinUI provides controls matching DINOForge&#39;s dark panel aesthetic</li><li>SDK (<code>netstandard2.0</code>) can be directly referenced from <code>net8.0-windows</code></li><li>TabView/NavigationView maps naturally to F9/F10 dual-panel concept</li></ul><p>Cons:</p><ul><li>Windows-only (acceptable — DINO is Windows-only)</li><li>WinUI 3 XAML tooling less mature than WPF</li></ul><h3 id="option-b-—-wpf" tabindex="-1">Option B — WPF <a class="header-anchor" href="#option-b-—-wpf" aria-label="Permalink to &quot;Option B — WPF&quot;">​</a></h3><p>Pros: Mature, widely documented Cons: No Mica, older visual design language, no Fluent controls</p><h3 id="option-c-—-maui" tabindex="-1">Option C — MAUI <a class="header-anchor" href="#option-c-—-maui" aria-label="Permalink to &quot;Option C — MAUI&quot;">​</a></h3><p>Pros: Cross-platform Cons: DINO is Windows-only; MAUI adds unnecessary complexity; desktop desktop performance overhead</p><h3 id="option-d-—-avalonia" tabindex="-1">Option D — Avalonia <a class="header-anchor" href="#option-d-—-avalonia" aria-label="Permalink to &quot;Option D — Avalonia&quot;">​</a></h3><p>Pros: Cross-platform, close to WPF Cons: Different theming system; DINO target audience is Windows users only</p><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Use WinUI 3 / WindowsAppSDK 1.6</strong> (Option A).</p><p>The companion is Windows-only by nature (mirrors an in-game Windows UI for a Windows game). WinUI 3 with Mica provides the highest fidelity match to the in-game <code>DFCanvas</code> dark theme and requires the least adaptation.</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/Tools/DesktopCompanion/</span></span>
<span class="line"><span>├── App.xaml + App.xaml.cs               # WinUI 3 app entry, WindowsAppSDK init</span></span>
<span class="line"><span>├── Program.cs                            # IHost bootstrap, unpackaged launch</span></span>
<span class="line"><span>├── MainWindow.xaml                       # NavigationView shell</span></span>
<span class="line"><span>├── Data/</span></span>
<span class="line"><span>│   ├── PackViewModel.cs                  # Local DTO (NOT Unity-dependent PackDisplayInfo)</span></span>
<span class="line"><span>│   ├── LoadResultViewModel.cs</span></span>
<span class="line"><span>│   ├── DebugSectionViewModel.cs</span></span>
<span class="line"><span>│   ├── IPackDataService.cs</span></span>
<span class="line"><span>│   ├── FileSystemPackDataService.cs      # Reads packs/ from filesystem</span></span>
<span class="line"><span>│   ├── DisabledPacksService.cs           # disabled_packs.json parity with game</span></span>
<span class="line"><span>│   └── AppConfigService.cs              # AppConfig.json persistence</span></span>
<span class="line"><span>├── ViewModels/</span></span>
<span class="line"><span>│   ├── MainViewModel.cs</span></span>
<span class="line"><span>│   ├── DashboardViewModel.cs</span></span>
<span class="line"><span>│   ├── PackListViewModel.cs</span></span>
<span class="line"><span>│   └── DebugPanelViewModel.cs</span></span>
<span class="line"><span>├── Views/</span></span>
<span class="line"><span>│   ├── DashboardPage.xaml</span></span>
<span class="line"><span>│   ├── PackListPage.xaml</span></span>
<span class="line"><span>│   ├── DebugPanelPage.xaml</span></span>
<span class="line"><span>│   └── SettingsPage.xaml</span></span>
<span class="line"><span>├── Themes/</span></span>
<span class="line"><span>│   ├── DinoForgeTheme.xaml               # Colour tokens matching DinoForgeStyle.cs</span></span>
<span class="line"><span>│   └── Converters/</span></span>
<span class="line"><span>└── HostBuilderExtensions.cs              # DI registrations</span></span></code></pre></div><h3 id="key-design-constraints" tabindex="-1">Key Design Constraints <a class="header-anchor" href="#key-design-constraints" aria-label="Permalink to &quot;Key Design Constraints&quot;">​</a></h3><ol><li><strong>No Unity dependency</strong> — <code>PackDisplayInfo</code> lives in DINOForge.Runtime (Unity-dependent). Companion defines its own <code>PackViewModel</code> DTO. SDK (<code>DINOForge.SDK.dll</code>) is safely referenceable.</li><li><strong>disabled_packs.json parity</strong> — Both game and companion must read/write the same JSON format to avoid desync.</li><li><strong>Wrap, don&#39;t handroll</strong> — All YAML parsing via YamlDotNet (already SDK dep), JSON via System.Text.Json.</li><li><strong>Unpackaged deployment</strong> — No MSIX; run directly from build output. WindowsAppSDK 1.6 supports this.</li><li><strong>IHostedService for file watching</strong> — Wraps <code>PackFileWatcher</code> (SDK) as background service; no custom polling.</li></ol><hr><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive</strong>:</p><ul><li>Pack author iteration loop drops from ~2min (game launch) to &lt;5s (companion refresh)</li><li>F9/F10 component layout changes can be evaluated in companion before committing to game launch</li><li>Companion can serve as standalone pack manager for end users</li></ul><p><strong>Negative</strong>:</p><ul><li>Windows-only distribution (acceptable given DINO platform)</li><li>Requires <code>WindowsAppSDK</code> runtime on developer machine</li><li>UI parity with in-game panels must be maintained when game panels change</li></ul><p><strong>Risks</strong>:</p><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Mitigation</th></tr></thead><tbody><tr><td>PackDisplayInfo data contract diverges from CompanionDTO</td><td>Medium</td><td>Define clear mapping in DisabledPacksService; integration test round-trip</td></tr><tr><td>SDK native deps (AssetsTools.NET) fail in unpackaged publish</td><td>Low</td><td>Verify sidecar DLLs in Phase 0 scaffold</td></tr><tr><td>CommunityToolkit.WinUI version lag</td><td>Low</td><td>Pin to stable 8.x release</td></tr><tr><td>disabled_packs.json format drift between game + companion</td><td>Medium</td><td>Shared JSON schema, shared test fixture</td></tr></tbody></table>`,39)])])}const m=n(i,[["render",t]]);export{u as __pageData,m as default};
